import (
	"reflect"
	"testing"
)

func mustErr(t *testing.T, path string) {
	t.Helper()
	got, err := Query(any(nil), path)
	if err == nil {
		t.Errorf("path %q: expected error, got %v", path, got)
	}
	if got != nil {
		t.Errorf("path %q: expected nil result, got %v", path, got)
	}
}

func TestTempEdgeCases(t *testing.T) {
	// malformed
	for _, p := range []string{"", "a.b", "$.", "$[", "$[1", `$["x]`, "$.1abc", "$[abc]", "$", "a", "$..", "$[\"ab\\", "$[1x]", "$[ 1]", "$x", "$[a"] {
		mustErr(t, p)
	}
	// $ alone
	d := map[string]any{"a": 1.0}
	if got, err := Query(d, "$"); err != nil || !reflect.DeepEqual(got, []any{d}) {
		t.Fatalf("%v %v", got, err)
	}
	// empty match -> non-nil empty
	if got, err := Query(d, "$.missing"); err != nil || got == nil || len(got) != 0 {
		t.Fatalf("%v %v", got, err)
	}
	// negative index
	a := []any{1.0, 2.0, 3.0}
	if got, err := Query(a, "$[-1]"); err != nil || !reflect.DeepEqual(got, []any{3.0}) {
		t.Fatalf("%v %v", got, err)
	}
	if got, err := Query(a, "$[-9]"); err != nil || len(got) != 0 {
		t.Fatalf("%v %v", got, err)
	}
	// wildcard on object, ordered by key
	o := map[string]any{"b": 2.0, "a": 1.0, "c": 3.0}
	if got, err := Query(o, "$.*"); err != nil || !reflect.DeepEqual(got, []any{1.0, 2.0, 3.0}) {
		t.Fatalf("%v %v", got, err)
	}
	// wildcard on non-container -> nothing
	if got, err := Query(5.0, "$.*"); err != nil || len(got) != 0 {
		t.Fatalf("%v %v", got, err)
	}
	// quoted key with escapes
	q := map[string]any{"a\"b": 1.0, `c\d`: 2.0}
	if got, err := Query(q, `$["a\\\"b"]`); err != nil || !reflect.DeepEqual(got, []any{1.0}) {
		t.Fatalf("%v %v", got, err)
	}
	if got, err := Query(q, `$["c\\\\d"]`); err != nil || !reflect.DeepEqual(got, []any{2.0}) {
		t.Fatalf("%v %v", got, err)
	}
	// ] inside quoted key
	q2 := map[string]any{"x]y": 7.0}
	if got, err := Query(q2, `$["x]y"]`); err != nil || !reflect.DeepEqual(got, []any{7.0}) {
		t.Fatalf("%v %v", got, err)
	}
	// recursive descent pre-order
	doc := map[string]any{
		"a":    1.0,
		"mid":  map[string]any{"a": 2.0, "z": []any{map[string]any{"a": 3.0}}},
		"deep": []any{map[string]any{"a": 4.0}},
	}
	if got, err := Query(doc, "$..a"); err != nil || !reflect.DeepEqual(got, []any{1.0, 2.0, 3.0, 4.0}) {
		t.Fatalf("%v %v", got, err)
	}
	// chained steps with multi-node input
	if got, err := Query(doc, `$..mid.*`); err != nil || !reflect.DeepEqual(got, []any{2.0, []any{map[string]any{"a": 3.0}}}) {
		t.Fatalf("%v %v", got, err)
	}
	// member on non-object -> nothing; index on non-array -> nothing
	s := "str"
	if got, err := Query(s, "$.x"); err != nil || len(got) != 0 {
		t.Fatalf("%v %v", got, err)
	}
	if got, err := Query(s, "$[0]"); err != nil || len(got) != 0 {
		t.Fatalf("%v %v", got, err)
	}
	// $[*] on scalar doc
	if got, err := Query(1.0, "$[*]"); err != nil || len(got) != 0 {
		t.Fatalf("%v %v", got, err)
	}
}
